 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Palette is a repeated multi-color row/column strip. Find repeated row runs
    # (demo 1) or repeated column runs (demo 2 and test).
    row_sigs = {}
    for r, row in enumerate(grid):
        if any(row):
            row_sigs.setdefault(tuple(row), []).append(r)
    band = max((rs for rs in row_sigs.values() if len(rs) >= 2), key=len, default=[])
    if band:
        colors = [v for v in grid[band[0]] if v]
        excluded_rows = set(band)
        excluded_cols = set()
        orientation = 'vertical'
    else:
        col_sigs = {}
        for c in range(w):
            col = tuple(grid[r][c] for r in range(h))
            if any(col):
                col_sigs.setdefault(col, []).append(c)
        bandc = max((cs for cs in col_sigs.values() if len(cs) >= 2), key=len, default=[])
        if not bandc:
            return grid
        colors = [grid[next(r for r in range(h) if grid[r][c]), c] for c in bandc]
        # Keep each unique adjacent palette color in spatial order.
        colors = []
        for c in bandc:
            color = next(grid[r][c] for r in range(h) if grid[r][c])
            if not colors or colors[-1] != color:
                colors.append(color)
        excluded_cols = set(bandc)
        excluded_rows = set()
        orientation = 'horizontal'
    pts = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] == 1 and r not in excluded_rows and c not in excluded_cols]
    if not pts or not colors:
        return grid
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    shape = [(r-r0, c-c0) for r, c in pts]
    out = [[0]*w for _ in range(h)]
    if orientation == 'vertical':
        step = r1-r0+1
        start = r0 - (len(colors)//2)*step
        for i, color in enumerate(colors):
            for dr, dc in shape:
                rr, cc = start + i*step + dr, c0 + dc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = color
    else:
        step = c1-c0+1
        start = c0 - (len(colors)//2)*step
        for i, color in enumerate(colors):
            for dr, dc in shape:
                rr, cc = r0 + dr, start + i*step + dc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = color
    return out
